/* SPDX-License-Identifier: MIT */
#include "providers/openai.h"

#include <jansson.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

#include "catalog.h"
#include "config.h"
#include "model_meta.h"
#include "provider.h"
#include "tool_schema.h"
#include "util.h"
#include "providers/openai_events.h"
#include "providers/openai_messages.h"
#include "providers/responses_events.h"
#include "providers/responses_messages.h"
#include "transport/api_error.h"
#include "transport/http.h"
#include "transport/retry.h"

#define AVAILABILITY_TIMEOUT_S 2
#define MODEL_LIST_TIMEOUT_S   10

const char *const OPENAI_EFFORT_LADDER[] = {"none", "minimal", "low", "medium",
                                            "high", "xhigh",   "max"};
const size_t OPENAI_EFFORT_LADDER_N =
    sizeof(OPENAI_EFFORT_LADDER) / sizeof(OPENAI_EFFORT_LADDER[0]);

struct openai {
    struct provider base;
    char *base_url;
    char *api_key;
    char *name;
    char *catalog_id;
    char *endpoint;
    char *session_id;
    int send_cache_key;
    int emit_progress;
    int request_cost;
    enum openai_cache_mode cache_mode;
    char *cache_ttl;
    char *reasoning_field;
    enum openai_reasoning_format reasoning_format;
    enum openai_wire wire;
    char **extra_headers;

    const char *length_hint;    /* borrowed for the provider lifetime */
    const char *const *efforts; /* borrowed for the provider lifetime */
    size_t n_efforts;
    void (*parse_model)(const json_t *entry, struct model_info *out);
};

/* AUTO sends explicit cache markers only when writes replace ordinary input processing. */
struct openai_cache_plan openai_plan_cache(const struct provider *provider, const char *model,
                                           enum openai_cache_mode mode, const char *ttl)
{
    struct openai_cache_plan plan = {0};
    struct catalog_entry rates;
    model_meta_rates(provider, model, &rates);
    plan.send_breakpoints = mode == OPENAI_CACHE_ON || (mode == OPENAI_CACHE_AUTO &&
                                                        catalog_cache_write_replaces_input(&rates));
    plan.writes_bill_1h = plan.send_breakpoints && ttl && strcasecmp(ttl, "1h") == 0 &&
                          rates.cost_cache_write_1h >= 0;
    return plan;
}

static json_t *build_chat_tools(const struct tool_def *tools, size_t n_tools)
{
    json_t *tool_list = json_array();
    for (size_t i = 0; i < n_tools; i++) {
        json_t *parameters = tool_schema_build(&tools[i]);
        json_array_append_new(tool_list, json_pack("{s:s, s:{s:s, s:s, s:o}}", "type", "function",
                                                   "function", "name", tools[i].name, "description",
                                                   tools[i].description, "parameters", parameters));
    }
    return tool_list;
}

static char *build_chat_body(const struct openai *openai, const struct context *context,
                             const char *model, const struct openai_cache_plan *cache)
{
    json_t *messages = openai_build_messages(context->system_prompt, context->items,
                                             context->n_items, openai->reasoning_field,
                                             openai->base.name, model, context->image_input);
    if (cache->send_breakpoints)
        openai_apply_cache_breakpoints(messages, openai->cache_ttl);

    /* Usage is requested on every stream so terminal events can report token counts. */
    json_t *body = json_pack("{s:s, s:b, s:o, s:{s:b}}", "model", model, "stream", 1, "messages",
                             messages, "stream_options", "include_usage", 1);

    if (context->n_tools > 0)
        json_object_set_new(body, "tools", build_chat_tools(context->tools, context->n_tools));
    if (openai->send_cache_key)
        json_object_set_new(body, "prompt_cache_key", json_string(openai->session_id));
    if (openai->emit_progress)
        json_object_set_new(body, "return_progress", json_true());
    if (openai->request_cost)
        json_object_set_new(body, "usage", json_pack("{s:b}", "include", 1));

    openai_apply_reasoning(body, openai->reasoning_format, context->effort);

    char *json = json_dumps(body, JSON_COMPACT);
    json_decref(body);
    return json;
}

static char *build_responses_body(const struct openai *openai, const struct context *context,
                                  const char *model)
{
    json_t *body = responses_build_body(context, openai->base.name, model);
    if (openai->send_cache_key)
        json_object_set_new(body, "prompt_cache_key", json_string(openai->session_id));

    char *json = json_dumps(body, JSON_COMPACT);
    json_decref(body);
    return json;
}

/* One parser per wire, behind a common interface so the retry loop stays protocol-agnostic. */
struct openai_parser {
    enum openai_wire wire;
    union {
        struct openai_events chat;
        struct responses_events responses;
    } u;
};

static void parser_init(struct openai_parser *parser, const struct openai *openai,
                        const struct openai_cache_plan *cache, stream_cb callback,
                        void *callback_user)
{
    parser->wire = openai->wire;
    if (parser->wire == OPENAI_WIRE_RESPONSES) {
        responses_events_init(&parser->u.responses, callback, callback_user);
        return;
    }

    openai_events_init(&parser->u.chat, callback, callback_user);
    parser->u.chat.emit_progress = openai->emit_progress;
    parser->u.chat.length_hint = openai->length_hint;
    parser->u.chat.cache_write_1h = cache->writes_bill_1h;
}

static void parser_finalize(struct openai_parser *parser)
{
    if (parser->wire == OPENAI_WIRE_RESPONSES)
        responses_events_finalize(&parser->u.responses);
    else
        openai_events_finalize(&parser->u.chat);
}

static void parser_free(struct openai_parser *parser)
{
    if (parser->wire == OPENAI_WIRE_RESPONSES)
        responses_events_free(&parser->u.responses);
    else
        openai_events_free(&parser->u.chat);
}

static const char **build_request_headers(const struct openai *openai, char **authorization)
{
    size_t n_extra_headers = 0;
    for (char **header = openai->extra_headers; header && *header; header++)
        n_extra_headers++;

    *authorization =
        openai->api_key ? xasprintf("Authorization: Bearer %s", openai->api_key) : NULL;
    const char **headers = xmalloc(sizeof(*headers) * (n_extra_headers + 4));
    size_t n_headers = 0;
    if (*authorization)
        headers[n_headers++] = *authorization;
    headers[n_headers++] = "Accept: text/event-stream";
    headers[n_headers++] = "Content-Type: application/json";
    for (char **header = openai->extra_headers; header && *header; header++)
        headers[n_headers++] = *header;
    headers[n_headers] = NULL;
    return headers;
}

static int handle_sse_data(const char *event_name, const char *data, void *user)
{
    (void)event_name;
    struct openai_parser *parser = user;
    if (parser->wire == OPENAI_WIRE_RESPONSES)
        responses_events_feed(&parser->u.responses, data);
    else
        openai_events_feed(&parser->u.chat, data);
    return 0;
}

static int openai_stream(struct provider *provider, const struct context *context,
                         const char *model, stream_cb callback, void *callback_user,
                         http_tick_cb tick, void *tick_user)
{
    struct openai *openai = (struct openai *)provider;

    /* Cache planning depends on rates populated by the startup metadata probe. Bounded: a
     * router-autoload probe can take minutes, while rate-reporting probes answer quickly, and the
     * request itself waits for the model to load anyway. */
    model_meta_wait_ms(provider, MODEL_META_PROBE_WAIT_MS);
    struct openai_cache_plan cache =
        openai_plan_cache(provider, model, openai->cache_mode, openai->cache_ttl);

    char *body = openai->wire == OPENAI_WIRE_RESPONSES
                     ? build_responses_body(openai, context, model)
                     : build_chat_body(openai, context, model, &cache);
    if (!body)
        return -1;

    size_t body_len = strlen(body);
    char *authorization;
    const char **headers = build_request_headers(openai, &authorization);
    struct retry_policy policy = retry_policy_default();
    struct http_response response;
    struct openai_parser parser;
    int result = -1;

    /* Each retry needs fresh parser state; request bytes remain safe to resend unchanged. */
    for (int attempt = 0; attempt < policy.max_attempts; attempt++) {
        memset(&response, 0, sizeof(response));
        parser_init(&parser, openai, &cache, callback, callback_user);

        result = http_sse_post(openai->endpoint, headers, body, body_len, policy.idle_timeout_s,
                               handle_sse_data, &parser, tick, tick_user, &response);
        if (response.cancelled ||
            !retry_should_attempt(result, response.status, response.error_body) ||
            attempt + 1 >= policy.max_attempts) {
            break;
        }

        long delay_ms = response.retry_after_ms > 0 ? response.retry_after_ms
                                                    : retry_delay_ms(&policy, attempt);
        struct stream_event retry = {
            .kind = EV_RETRY,
            .u.retry =
                {
                    .attempt = attempt + 1,
                    .max_attempts = policy.max_attempts,
                    .delay_ms = delay_ms,
                    .http_status = (int)response.status,
                },
        };
        callback(&retry, callback_user);

        free(response.error_body);
        response.error_body = NULL;
        parser_free(&parser);

        if (retry_sleep_with_tick(delay_ms, tick, tick_user)) {
            response.cancelled = 1;
            parser_init(&parser, openai, &cache, callback, callback_user);
            break;
        }
    }

    if (!response.cancelled) {
        if (result != 0 || response.status < 200 || response.status >= 300) {
            char *message = format_api_error(response.status, response.error_body);
            struct stream_event error = {
                .kind = EV_ERROR,
                .u.error = {.message = message, .http_status = (int)response.status},
            };
            callback(&error, callback_user);
            free(message);
        } else {
            parser_finalize(&parser);
        }
    }

    free(response.error_body);
    parser_free(&parser);
    free(headers);
    free(authorization);
    free(body);
    return result;
}

static void openai_destroy(struct provider *provider)
{
    struct openai *openai = (struct openai *)provider;
    model_meta_release(provider);
    free(openai->base_url);
    free(openai->api_key);
    free(openai->name);
    free(openai->catalog_id);
    free(openai->endpoint);
    free(openai->session_id);
    free(openai->cache_ttl);
    free(openai->reasoning_field);
    string_array_free(openai->extra_headers);
    free(openai);
}

static char **duplicate_headers(const char *const *headers)
{
    if (!headers || !*headers)
        return NULL;

    size_t n_headers = 0;
    while (headers[n_headers])
        n_headers++;

    char **copy = xmalloc(sizeof(*copy) * (n_headers + 1));
    for (size_t i = 0; i < n_headers; i++)
        copy[i] = xstrdup(headers[i]);
    copy[n_headers] = NULL;
    return copy;
}

enum openai_wire openai_wire_parse(const char *value, enum openai_wire fallback)
{
    if (!value || !*value)
        return fallback;
    if (strcasecmp(value, "chat") == 0 || strcasecmp(value, "openai-completions") == 0)
        return OPENAI_WIRE_CHAT;
    if (strcasecmp(value, "responses") == 0 || strcasecmp(value, "openai-responses") == 0)
        return OPENAI_WIRE_RESPONSES;

    hax_warn("unknown api %s (expected 'chat' or 'responses') — using default", value);
    return fallback;
}

static char *make_config_key(const char *prefix, const char *leaf)
{
    return xasprintf("%s.%s", prefix ? prefix : "openai", leaf);
}

static const char *preset_config(const char *prefix, const char *leaf)
{
    char *key = make_config_key(prefix, leaf);
    const char *value = config_str(key);
    free(key);
    return value;
}

static int preset_bool(const char *prefix, const char *leaf, int fallback)
{
    char *key = make_config_key(prefix, leaf);
    int value = config_bool_or(key, fallback);
    free(key);
    return value;
}

static enum openai_cache_mode resolve_cache_mode(const char *prefix, int automatic)
{
    char *key = make_config_key(prefix, "cache");

    /* Different fallbacks distinguish a parsed boolean from auto, unset, or invalid input. */
    int with_false_fallback = config_bool_or(key, 0);
    int with_true_fallback = config_bool_or(key, 1);
    free(key);

    if (with_false_fallback == with_true_fallback)
        return with_true_fallback ? OPENAI_CACHE_ON : OPENAI_CACHE_OFF;
    return automatic ? OPENAI_CACHE_AUTO : OPENAI_CACHE_OFF;
}

static char *resolve_reasoning_field(const char *prefix, const char *preset_default)
{
    const char *configured = preset_config(prefix, "reasoning_roundtrip");
    const char *field = preset_default;
    if (configured) {
        if (!*configured || strcmp(configured, "off") == 0 || strcmp(configured, "0") == 0)
            field = NULL;
        else if (strcmp(configured, "on") == 0 || strcmp(configured, "1") == 0)
            field = "reasoning_content";
        else
            field = configured;
    }
    return field ? xstrdup(field) : NULL;
}

static int openai_list_models(struct provider *provider, struct model_info **models,
                              size_t *n_models, char **error, http_tick_cb tick, void *tick_user)
{
    struct openai *openai = (struct openai *)provider;
    *models = NULL;
    *n_models = 0;

    char *url = xasprintf("%s/models", openai->base_url);
    char *authorization =
        openai->api_key ? xasprintf("Authorization: Bearer %s", openai->api_key) : NULL;
    const char *headers[] = {authorization, NULL};
    char *response_body = NULL;
    long status = 0;
    int result = http_get(url, authorization ? headers : NULL, MODEL_LIST_TIMEOUT_S, 0, tick,
                          tick_user, &response_body, &status);
    free(authorization);
    free(url);

    if (result != 0) {
        *error = format_model_list_error(provider->name, openai->base_url, openai->api_key != NULL,
                                         status);
        free(response_body);
        return -1;
    }

    json_t *root = json_loads(response_body, 0, NULL);
    free(response_body);
    const char *provider_name = provider->name ? provider->name : "provider";
    if (!root) {
        *error = xasprintf("%s /models response is not valid JSON", provider_name);
        return -1;
    }

    json_t *data = json_object_get(root, "data");
    /* Ollama reports data:null when the server is reachable but has no models. */
    if (json_is_null(data) || (json_is_array(data) && json_array_size(data) == 0)) {
        json_decref(root);
        return 0;
    }
    if (!json_is_array(data)) {
        json_decref(root);
        *error = xasprintf("%s /models response has no model list", provider_name);
        return -1;
    }

    size_t n_entries = json_array_size(data);
    struct model_info *available = xmalloc(n_entries * sizeof(*available));
    size_t n_available = 0;
    for (size_t i = 0; i < n_entries; i++) {
        json_t *entry = json_array_get(data, i);
        const char *model_id = json_string_value(json_object_get(entry, "id"));
        if (!model_id || !*model_id)
            continue;

        model_info_init(&available[n_available]);
        available[n_available].id = xstrdup(model_id);
        if (openai->parse_model)
            openai->parse_model(entry, &available[n_available]);
        n_available++;
    }
    json_decref(root);

    if (n_available == 0) {
        free(available);
        *error = xasprintf("%s /models response contains no usable model ids", provider_name);
        return -1;
    }

    *models = available;
    *n_models = n_available;
    return 0;
}

static size_t openai_list_efforts(struct provider *provider, const char *const **efforts)
{
    struct openai *openai = (struct openai *)provider;
    if (!openai->efforts || openai->n_efforts == 0)
        return 0;
    *efforts = openai->efforts;
    return openai->n_efforts;
}

int openai_key_available(const char *api_key_env, const char *missing_reason, const char **reason)
{
    const char *key = config_str("openai.api_key");
    if (key && *key)
        return 1;
    if (api_key_env) {
        key = getenv(api_key_env);
        if (key && *key)
            return 1;
    }
    if (reason)
        *reason = missing_reason ? missing_reason : "no API key";
    return 0;
}

void openai_prepare_base_url_availability(const char *base_url, const char *api_key,
                                          struct provider_availability *out)
{
    out->available = 0;
    out->reason = "server not reachable";
    out->url = xasprintf("%s/models", base_url);
    out->timeout_s = AVAILABILITY_TIMEOUT_S;
    if (api_key && *api_key) {
        out->headers = xcalloc(2, sizeof(*out->headers));
        out->headers[0] = xasprintf("Authorization: Bearer %s", api_key);
    }
}

static void openai_prepare_availability(const char *name, struct provider_availability *out)
{
    (void)name;
    const char *reason = NULL;
    out->available = openai_key_available("OPENAI_API_KEY", "OPENAI_API_KEY not set", &reason);
    out->reason = reason;
}

static char *resolve_base_url(const struct openai_preset *preset)
{
    const char *configured =
        preset->lock_base_url ? NULL : preset_config(preset->config_prefix, "base_url");
    const char *base_url = configured && *configured ? configured : preset->default_base_url;
    if (!base_url || !*base_url) {
        hax_err("internal: openai preset has no base URL");
        return NULL;
    }
    return dup_trim_trailing_slash(base_url);
}

static const char *resolve_api_key(const struct openai_preset *preset)
{
    const char *api_key = preset_config(preset->config_prefix, "api_key");
    if ((!api_key || !*api_key) && preset->api_key_env)
        api_key = getenv(preset->api_key_env);
    return api_key;
}

static const char *resolve_display_name(const struct openai_preset *preset)
{
    const char *name = preset->config_prefix ? NULL : config_str("provider_name");
    if (name && *name)
        return name;
    if (preset->display_name && *preset->display_name)
        return preset->display_name;
    return "openai";
}

struct provider *openai_provider_new_preset(const struct openai_preset *preset)
{
    const struct openai_preset empty = {0};
    if (!preset)
        preset = &empty;

    char *base_url = resolve_base_url(preset);
    if (!base_url)
        return NULL;

    struct openai *openai = xcalloc(1, sizeof(*openai));
    openai->base_url = base_url;
    const char *api_key = resolve_api_key(preset);
    openai->api_key = api_key && *api_key ? xstrdup(api_key) : NULL;
    openai->name = xstrdup(resolve_display_name(preset));
    openai->catalog_id = preset->catalog_id ? xstrdup(preset->catalog_id) : NULL;
    openai->wire = openai_wire_parse(preset_config(preset->config_prefix, "api"), preset->wire);
    openai->endpoint =
        xasprintf("%s/%s", openai->base_url,
                  openai->wire == OPENAI_WIRE_RESPONSES ? "responses" : "chat/completions");

    openai->send_cache_key =
        preset_bool(preset->config_prefix, "send_cache_key", preset->send_cache_key_default);
    openai->emit_progress = preset->emit_progress;
    openai->request_cost = preset_bool(preset->config_prefix, "request_cost", preset->request_cost);
    openai->cache_mode = resolve_cache_mode(preset->config_prefix, preset->cache_auto_default);
    const char *cache_ttl = preset_config(preset->config_prefix, "cache_ttl");
    openai->cache_ttl = xstrdup(cache_ttl ? cache_ttl : "");
    openai->reasoning_field =
        resolve_reasoning_field(preset->config_prefix, preset->reasoning_replay_field);
    openai->reasoning_format = preset->reasoning_format;
    openai->extra_headers = duplicate_headers(preset->extra_headers);

    openai->length_hint = preset->length_hint;
    openai->efforts = preset->efforts;
    openai->n_efforts = preset->n_efforts;
    openai->parse_model = preset->parse_model;

    char session_id[37];
    gen_uuid_v4(session_id);
    openai->session_id = xstrdup(session_id);

    openai->base.name = openai->name;
    openai->base.catalog_id = openai->catalog_id;
    openai->base.stream = openai_stream;
    openai->base.list_models = openai_list_models;
    openai->base.list_efforts = openai_list_efforts;
    openai->base.destroy = openai_destroy;
    return &openai->base;
}

struct provider *openai_provider_new(const char *name)
{
    (void)name;
    /* Lock the host so OPENAI_API_KEY and OpenAI-specific defaults cannot reach a custom URL. */
    struct openai_preset preset = {
        .display_name = "openai",
        .default_base_url = "https://api.openai.com/v1",
        .api_key_env = "OPENAI_API_KEY",
        .send_cache_key_default = 1,
        .lock_base_url = 1,
        .wire = OPENAI_WIRE_RESPONSES,
        .catalog_id = "openai",
        .efforts = OPENAI_EFFORT_LADDER,
        .n_efforts = OPENAI_EFFORT_LADDER_N,
    };
    struct provider *provider = openai_provider_new_preset(&preset);
    if (provider)
        provider->sort_models = 1;
    return provider;
}

const struct provider_factory PROVIDER_OPENAI = {
    .name = "openai",
    .new = openai_provider_new,
    .prepare_availability = openai_prepare_availability,
};

/* SPDX-License-Identifier: MIT */
#include "providers/anthropic.h"

#include <jansson.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

#include "config.h"
#include "effort.h"
#include "model_meta.h"
#include "provider.h"
#include "tool_schema.h"
#include "util.h"
#include "providers/anthropic_events.h"
#include "providers/anthropic_messages.h"
#include "transport/api_error.h"
#include "transport/http.h"
#include "transport/retry.h"

#define ANTHROPIC_DEFAULT_VERSION    "2023-06-01"
#define ANTHROPIC_DEFAULT_MAX_TOKENS 32000

/* Bound foreground pagination if a server keeps returning advancing cursors. */
#define ANTHROPIC_MODEL_PAGE_SIZE  1000
#define ANTHROPIC_MODEL_PAGE_LIMIT 50

#define MODEL_LIST_TIMEOUT_S  10
#define MODEL_PROBE_TIMEOUT_S 5

const char *const ANTHROPIC_EFFORT_LADDER[] = {"low", "medium", "high", "xhigh", "max"};
const size_t ANTHROPIC_EFFORT_LADDER_N =
    sizeof(ANTHROPIC_EFFORT_LADDER) / sizeof(ANTHROPIC_EFFORT_LADDER[0]);

struct anthropic {
    struct provider base;
    char *base_url;
    char *api_key;
    char *name;
    char *catalog_id;
    char *endpoint;
    char *version;
    char *config_prefix;
    enum anthropic_thinking_mode default_thinking_mode;
    int allow_empty_signature;
    int cache_default;
};

static char *make_config_key(const char *prefix, const char *leaf)
{
    return xasprintf("%s.%s", prefix ? prefix : "anthropic", leaf);
}

static const char *preset_config(const char *prefix, const char *leaf)
{
    char *key = make_config_key(prefix, leaf);
    const char *value = config_str(key);
    free(key);
    return value;
}

static int preset_bool(const char *prefix, const char *leaf, int fallback)
{
    char *key = make_config_key(prefix, leaf);
    int value = config_bool_or(key, fallback);
    free(key);
    return value;
}

static int preset_int(const char *prefix, const char *leaf)
{
    char *key = make_config_key(prefix, leaf);
    int value = config_int(key);
    free(key);
    return value;
}

static json_t *build_cache_control(const char *ttl)
{
    json_t *cache_control = json_pack("{s:s}", "type", "ephemeral");
    if (ttl && strcasecmp(ttl, "1h") == 0)
        json_object_set_new(cache_control, "ttl", json_string("1h"));
    return cache_control;
}

static json_t *build_tools(const struct tool_def *tools, size_t n_tools, int cache_last,
                           const char *ttl)
{
    json_t *tool_list = json_array();
    for (size_t i = 0; i < n_tools; i++) {
        json_t *schema = tool_schema_build(&tools[i]);
        json_t *tool = json_pack("{s:s, s:s, s:o}", "name", tools[i].name, "description",
                                 tools[i].description, "input_schema", schema);
        if (cache_last && i == n_tools - 1)
            json_object_set_new(tool, "cache_control", build_cache_control(ttl));
        json_array_append_new(tool_list, tool);
    }
    return tool_list;
}

static void attach_cache_to_last_message(json_t *messages, const char *ttl)
{
    size_t n_messages = json_array_size(messages);
    if (n_messages == 0)
        return;

    json_t *message = json_array_get(messages, n_messages - 1);
    json_t *content = json_object_get(message, "content");
    if (!json_is_array(content) || json_array_size(content) == 0)
        return;

    json_t *block = json_array_get(content, json_array_size(content) - 1);
    const char *type = json_string_value(json_object_get(block, "type"));
    /* Anthropic rejects cache_control on thinking blocks. */
    if (type && (strcmp(type, "thinking") == 0 || strcmp(type, "redacted_thinking") == 0))
        return;
    json_object_set_new(block, "cache_control", build_cache_control(ttl));
}

static enum anthropic_thinking_mode resolve_thinking_mode(const struct anthropic *anthropic)
{
    const char *configured = preset_config(anthropic->config_prefix, "thinking_mode");
    if (!configured || !*configured)
        return anthropic->default_thinking_mode;
    if (strcasecmp(configured, "adaptive") == 0)
        return ANTHROPIC_THINKING_ADAPTIVE;
    if (strcasecmp(configured, "budget") == 0)
        return ANTHROPIC_THINKING_BUDGET;
    if (strcasecmp(configured, "off") == 0)
        return ANTHROPIC_THINKING_OFF;

    hax_warn("unknown anthropic.thinking_mode '%s' (adaptive/budget/off) — using default",
             configured);
    return anthropic->default_thinking_mode;
}

static void apply_thinking(json_t *body, const struct anthropic *anthropic,
                           const struct context *context, int max_tokens)
{
    enum anthropic_thinking_mode mode = resolve_thinking_mode(anthropic);
    if (mode == ANTHROPIC_THINKING_OFF)
        return;

    if (mode == ANTHROPIC_THINKING_ADAPTIVE) {
        const char *display = config_bool("show_reasoning") ? "summarized" : "omitted";
        json_object_set_new(body, "thinking",
                            json_pack("{s:s, s:s}", "type", "adaptive", "display", display));
        if (context->effort && *context->effort) {
            json_object_set_new(body, "output_config",
                                json_pack("{s:s}", "effort", context->effort));
        }
        return;
    }

    /* Anthropic requires 1 <= budget_tokens < max_tokens. */
    if (max_tokens < 2)
        return;
    int budget_tokens = preset_int(anthropic->config_prefix, "thinking_budget");
    if (budget_tokens <= 0 || budget_tokens >= max_tokens)
        budget_tokens = max_tokens - 1;
    json_object_set_new(body, "thinking",
                        json_pack("{s:s, s:i}", "type", "enabled", "budget_tokens", budget_tokens));
}

int anthropic_max_tokens(struct provider *provider, const char *model)
{
    struct anthropic *anthropic = (struct anthropic *)provider;
    char *key = make_config_key(anthropic->config_prefix, "max_tokens");
    int configured = config_int(key);
    int user_set = strcmp(config_source(key), "default") != 0;
    free(key);

    long model_limit = model_meta_max_output(provider, model);
    if (user_set && configured > 0)
        return model_limit > 0 && configured > model_limit ? (int)model_limit : configured;
    if (model_limit > 0)
        return (int)model_limit;
    return configured > 0 ? configured : ANTHROPIC_DEFAULT_MAX_TOKENS;
}

static char *build_request_body(struct anthropic *anthropic, const struct context *context,
                                const char *model)
{
    int max_tokens = anthropic_max_tokens(&anthropic->base, model);
    int cache = preset_bool(anthropic->config_prefix, "cache", anthropic->cache_default);
    const char *cache_ttl = preset_config(anthropic->config_prefix, "cache_ttl");

    json_t *messages =
        anthropic_build_messages(context->items, context->n_items, anthropic->base.name, model,
                                 anthropic->allow_empty_signature, context->image_input);
    json_t *body = json_pack("{s:s, s:i, s:b, s:o}", "model", model, "max_tokens", max_tokens,
                             "stream", 1, "messages", messages);

    if (context->system_prompt && *context->system_prompt) {
        json_t *system_block =
            json_pack("{s:s, s:s}", "type", "text", "text", context->system_prompt);
        if (cache)
            json_object_set_new(system_block, "cache_control", build_cache_control(cache_ttl));
        json_t *system = json_array();
        json_array_append_new(system, system_block);
        json_object_set_new(body, "system", system);
    }

    if (context->n_tools > 0) {
        json_object_set_new(body, "tools",
                            build_tools(context->tools, context->n_tools, cache, cache_ttl));
    }
    if (cache)
        attach_cache_to_last_message(messages, cache_ttl);

    apply_thinking(body, anthropic, context, max_tokens);

    char *json = json_dumps(body, JSON_COMPACT);
    json_decref(body);
    return json;
}

static int handle_sse_data(const char *event_name, const char *data, void *user)
{
    anthropic_events_feed(user, event_name, data);
    return 0;
}

static int anthropic_stream(struct provider *provider, const struct context *context,
                            const char *model, stream_cb callback, void *callback_user,
                            http_tick_cb tick, void *tick_user)
{
    struct anthropic *anthropic = (struct anthropic *)provider;

    char *body = build_request_body(anthropic, context, model);
    if (!body)
        return -1;

    size_t body_len = strlen(body);
    char *api_key_header =
        anthropic->api_key ? xasprintf("x-api-key: %s", anthropic->api_key) : NULL;
    char *version_header = xasprintf("anthropic-version: %s", anthropic->version);
    const char *headers[] = {api_key_header, version_header, "Accept: text/event-stream",
                             "Content-Type: application/json", NULL};
    const char **request_headers = api_key_header ? headers : &headers[1];

    struct retry_policy policy = retry_policy_default();
    struct http_response response;
    struct anthropic_events parser;
    int result = -1;

    /* Each retry needs fresh parser state; request bytes are safe to resend unchanged. */
    for (int attempt = 0; attempt < policy.max_attempts; attempt++) {
        memset(&response, 0, sizeof(response));
        anthropic_events_init(&parser, callback, callback_user);
        result = http_sse_post(anthropic->endpoint, request_headers, body, body_len,
                               policy.idle_timeout_s, handle_sse_data, &parser, tick, tick_user,
                               &response);

        if (response.cancelled ||
            !retry_should_attempt(result, response.status, response.error_body) ||
            attempt + 1 >= policy.max_attempts) {
            break;
        }

        long delay_ms = response.retry_after_ms > 0 ? response.retry_after_ms
                                                    : retry_delay_ms(&policy, attempt);
        struct stream_event retry = {
            .kind = EV_RETRY,
            .u.retry =
                {
                    .attempt = attempt + 1,
                    .max_attempts = policy.max_attempts,
                    .delay_ms = delay_ms,
                    .http_status = (int)response.status,
                },
        };
        callback(&retry, callback_user);

        free(response.error_body);
        response.error_body = NULL;
        anthropic_events_free(&parser);

        if (retry_sleep_with_tick(delay_ms, tick, tick_user)) {
            response.cancelled = 1;
            memset(&parser, 0, sizeof(parser));
            break;
        }
    }

    if (!response.cancelled) {
        if (result != 0 || response.status < 200 || response.status >= 300) {
            char *message = format_api_error(response.status, response.error_body);
            struct stream_event error = {
                .kind = EV_ERROR,
                .u.error = {.message = message, .http_status = (int)response.status},
            };
            callback(&error, callback_user);
            free(message);
        } else {
            anthropic_events_finalize(&parser);
        }
    }

    free(response.error_body);
    anthropic_events_free(&parser);
    free(api_key_header);
    free(version_header);
    free(body);
    return result;
}

static void parse_model_efforts(json_t *effort, struct effort_set *out)
{
    if (json_is_false(json_object_get(effort, "supported"))) {
        out->known = 1;
        return;
    }
    if (!json_is_object(effort))
        return;

    /* Preserve the picker order rather than the JSON object's member order. */
    for (size_t i = 0; i < ANTHROPIC_EFFORT_LADDER_N; i++) {
        json_t *level = json_object_get(effort, ANTHROPIC_EFFORT_LADDER[i]);
        if (json_is_object(level) && json_is_true(json_object_get(level, "supported")))
            effort_set_add(out, ANTHROPIC_EFFORT_LADDER[i]);
    }

    const char *name;
    json_t *level;
    json_object_foreach(effort, name, level)
    {
        if (strcmp(name, "supported") != 0 && json_is_object(level) &&
            json_is_true(json_object_get(level, "supported"))) {
            effort_set_add(out, name);
        }
    }
}

void anthropic_parse_model(const json_t *entry, struct model_info *out)
{
    json_t *max_input = json_object_get(entry, "max_input_tokens");
    if (json_is_integer(max_input) && json_integer_value(max_input) > 0)
        out->context = (long)json_integer_value(max_input);

    json_t *max_output = json_object_get(entry, "max_tokens");
    if (json_is_integer(max_output) && json_integer_value(max_output) > 0)
        out->max_output = (long)json_integer_value(max_output);

    json_t *capabilities = json_object_get(entry, "capabilities");
    json_t *image = json_object_get(capabilities, "image_input");
    json_t *image_supported = json_object_get(image, "supported");
    if (json_is_boolean(image_supported)) {
        out->image_input = json_is_true(image_supported) ? PROVIDER_CAP_YES : PROVIDER_CAP_NO;
    }

    parse_model_efforts(json_object_get(capabilities, "effort"), &out->efforts);
}

static void parse_model_probe_response(const char *response_body, const char *model,
                                       struct model_info *out)
{
    json_t *root = json_loads(response_body, 0, NULL);
    if (!root)
        return;

    json_t *data = json_object_get(root, "data");
    size_t index;
    json_t *entry;
    json_array_foreach(data, index, entry)
    {
        const char *model_id = json_string_value(json_object_get(entry, "id"));
        if (model_id && strcmp(model_id, model) == 0) {
            anthropic_parse_model(entry, out);
            break;
        }
    }
    json_decref(root);
}

static int anthropic_probe_model(struct provider *provider, const char *model,
                                 struct model_probe *probe)
{
    struct anthropic *anthropic = (struct anthropic *)provider;
    if (!model || !*model)
        return -1;

    probe->url = xasprintf("%s/models?limit=%d", anthropic->base_url, ANTHROPIC_MODEL_PAGE_SIZE);
    probe->headers = xcalloc(3, sizeof(*probe->headers));
    size_t n_headers = 0;
    if (anthropic->api_key)
        probe->headers[n_headers++] = xasprintf("x-api-key: %s", anthropic->api_key);
    probe->headers[n_headers++] = xasprintf("anthropic-version: %s", anthropic->version);
    probe->headers[n_headers] = NULL;
    probe->timeout_s = MODEL_PROBE_TIMEOUT_S;
    probe->parse = parse_model_probe_response;
    return 0;
}

/* The server-provided cursor is inserted into a query parameter without encoding. */
static int cursor_is_safe(const char *cursor)
{
    if (!cursor || !*cursor)
        return 0;
    for (const char *byte = cursor; *byte; byte++) {
        int safe = (*byte >= 'A' && *byte <= 'Z') || (*byte >= 'a' && *byte <= 'z') ||
                   (*byte >= '0' && *byte <= '9') || *byte == '.' || *byte == '_' || *byte == '-';
        if (!safe)
            return 0;
    }
    return 1;
}

/* On success, `page` owns the parsed response. */
static int fetch_models_page(const struct anthropic *anthropic, const char *after_id,
                             http_tick_cb tick, void *tick_user, json_t **page, char **error)
{
    char *url =
        after_id ? xasprintf("%s/models?limit=%d&after_id=%s", anthropic->base_url,
                             ANTHROPIC_MODEL_PAGE_SIZE, after_id)
                 : xasprintf("%s/models?limit=%d", anthropic->base_url, ANTHROPIC_MODEL_PAGE_SIZE);
    char *api_key_header =
        anthropic->api_key ? xasprintf("x-api-key: %s", anthropic->api_key) : NULL;
    char *version_header = xasprintf("anthropic-version: %s", anthropic->version);
    const char *headers[] = {api_key_header, version_header, NULL};
    const char **request_headers = api_key_header ? headers : &headers[1];

    char *response_body = NULL;
    long status = 0;
    int result = http_get(url, request_headers, MODEL_LIST_TIMEOUT_S, 0, tick, tick_user,
                          &response_body, &status);
    free(api_key_header);
    free(version_header);
    free(url);

    if (result != 0) {
        *error = format_model_list_error(anthropic->base.name, anthropic->base_url,
                                         anthropic->api_key != NULL, status);
        free(response_body);
        return -1;
    }

    *page = json_loads(response_body, 0, NULL);
    free(response_body);
    if (!*page) {
        const char *provider_name = anthropic->base.name ? anthropic->base.name : "provider";
        *error = xasprintf("%s /models response is not valid JSON", provider_name);
        return -1;
    }
    return 0;
}

static void append_models(json_t *data, struct model_info **models, size_t *n_models,
                          size_t *capacity, int *saw_entry)
{
    size_t n_entries = json_array_size(data);
    for (size_t i = 0; i < n_entries; i++) {
        json_t *entry = json_array_get(data, i);
        const char *model_id = json_string_value(json_object_get(entry, "id"));
        *saw_entry = 1;
        if (!model_id || !*model_id)
            continue;

        if (*n_models == *capacity) {
            *capacity = *capacity ? *capacity * 2 : (n_entries > 8 ? n_entries : 8);
            *models = xrealloc(*models, *capacity * sizeof(**models));
        }
        model_info_init(&(*models)[*n_models]);
        (*models)[*n_models].id = xstrdup(model_id);
        anthropic_parse_model(entry, &(*models)[*n_models]);
        (*n_models)++;
    }
}

static int anthropic_list_models(struct provider *provider, struct model_info **models,
                                 size_t *n_models, char **error, http_tick_cb tick, void *tick_user)
{
    struct anthropic *anthropic = (struct anthropic *)provider;
    *models = NULL;
    *n_models = 0;

    struct model_info *available = NULL;
    size_t n_available = 0;
    size_t capacity = 0;
    char *after_id = NULL;
    int saw_entry = 0;

    for (int page_number = 0; page_number < ANTHROPIC_MODEL_PAGE_LIMIT; page_number++) {
        json_t *page = NULL;
        if (fetch_models_page(anthropic, after_id, tick, tick_user, &page, error) != 0)
            goto fail;

        json_t *data = json_object_get(page, "data");
        if (!json_is_array(data) && !json_is_null(data)) {
            json_decref(page);
            const char *name = provider->name ? provider->name : "provider";
            *error = xasprintf("%s /models response has no model list", name);
            goto fail;
        }

        const char *last_id = json_string_value(json_object_get(page, "last_id"));
        /* Discard a repeated page before it can duplicate models already collected. */
        if (after_id && last_id && strcmp(after_id, last_id) == 0) {
            json_decref(page);
            break;
        }

        append_models(data, &available, &n_available, &capacity, &saw_entry);
        int has_more = json_is_true(json_object_get(page, "has_more"));
        free(after_id);
        after_id = has_more && cursor_is_safe(last_id) ? xstrdup(last_id) : NULL;
        json_decref(page);
        if (!after_id)
            break;
    }
    free(after_id);

    if (saw_entry && n_available == 0) {
        const char *name = provider->name ? provider->name : "provider";
        *error = xasprintf("%s /models response contains no usable model ids", name);
        model_info_free(available, n_available);
        return -1;
    }

    *models = available;
    *n_models = n_available;
    return 0;

fail:
    free(after_id);
    model_info_free(available, n_available);
    return -1;
}

static size_t anthropic_list_efforts(struct provider *provider, const char *const **efforts)
{
    struct anthropic *anthropic = (struct anthropic *)provider;
    if (resolve_thinking_mode(anthropic) != ANTHROPIC_THINKING_ADAPTIVE)
        return 0;
    *efforts = ANTHROPIC_EFFORT_LADDER;
    return ANTHROPIC_EFFORT_LADDER_N;
}

static void anthropic_destroy(struct provider *provider)
{
    struct anthropic *anthropic = (struct anthropic *)provider;
    model_meta_release(provider);
    free(anthropic->base_url);
    free(anthropic->api_key);
    free(anthropic->name);
    free(anthropic->catalog_id);
    free(anthropic->endpoint);
    free(anthropic->version);
    free(anthropic->config_prefix);
    free(anthropic);
}

static char *resolve_base_url(const struct anthropic_preset *preset)
{
    const char *configured =
        preset->lock_base_url ? NULL : preset_config(preset->config_prefix, "base_url");
    const char *base_url = configured && *configured ? configured : preset->default_base_url;
    if (!base_url || !*base_url) {
        hax_err("internal: anthropic preset has no base URL");
        return NULL;
    }
    return dup_trim_trailing_slash(base_url);
}

static const char *resolve_api_key(const struct anthropic_preset *preset)
{
    const char *api_key = preset_config(preset->config_prefix, "api_key");
    if ((!api_key || !*api_key) && preset->api_key_env)
        api_key = getenv(preset->api_key_env);
    return api_key;
}

static const char *resolve_display_name(const struct anthropic_preset *preset)
{
    const char *name = preset->config_prefix ? NULL : config_str("provider_name");
    if (name && *name)
        return name;
    if (preset->display_name && *preset->display_name)
        return preset->display_name;
    return "anthropic";
}

struct provider *anthropic_provider_new_preset(const struct anthropic_preset *preset)
{
    const struct anthropic_preset empty = {0};
    if (!preset)
        preset = &empty;

    char *base_url = resolve_base_url(preset);
    if (!base_url)
        return NULL;

    struct anthropic *anthropic = xcalloc(1, sizeof(*anthropic));
    anthropic->base_url = base_url;
    const char *api_key = resolve_api_key(preset);
    anthropic->api_key = api_key && *api_key ? xstrdup(api_key) : NULL;
    anthropic->name = xstrdup(resolve_display_name(preset));
    anthropic->catalog_id = preset->catalog_id ? xstrdup(preset->catalog_id) : NULL;
    anthropic->endpoint = xasprintf("%s/messages", anthropic->base_url);
    const char *version = preset_config(preset->config_prefix, "version");
    anthropic->version = xstrdup(version && *version ? version : ANTHROPIC_DEFAULT_VERSION);
    anthropic->config_prefix = preset->config_prefix ? xstrdup(preset->config_prefix) : NULL;
    anthropic->default_thinking_mode = preset->default_thinking_mode;
    anthropic->allow_empty_signature = preset->allow_empty_signature;
    anthropic->cache_default = preset->send_cache_control_default;

    anthropic->base.name = anthropic->name;
    anthropic->base.catalog_id = anthropic->catalog_id;
    anthropic->base.stream = anthropic_stream;
    anthropic->base.list_models = anthropic_list_models;
    anthropic->base.list_efforts = anthropic_list_efforts;
    anthropic->base.probe_model = anthropic_probe_model;
    anthropic->base.destroy = anthropic_destroy;

    const char *configured_model = config_str("model");
    model_meta_refresh(&anthropic->base,
                       configured_model && *configured_model ? configured_model : NULL);
    return &anthropic->base;
}

struct provider *anthropic_provider_new(const char *name)
{
    (void)name;
    struct anthropic_preset preset = {
        .display_name = "anthropic",
        .default_base_url = "https://api.anthropic.com/v1",
        .api_key_env = "ANTHROPIC_API_KEY",
        .lock_base_url = 1,
        .default_thinking_mode = ANTHROPIC_THINKING_ADAPTIVE,
        .allow_empty_signature = 0,
        .send_cache_control_default = 1,
        .catalog_id = "anthropic",
    };
    return anthropic_provider_new_preset(&preset);
}

static int anthropic_key_available(const char *api_key_env, const char **reason)
{
    const char *key = config_str("anthropic.api_key");
    if (key && *key)
        return 1;
    if (api_key_env) {
        const char *e = getenv(api_key_env);
        if (e && *e)
            return 1;
    }
    if (reason)
        *reason = "ANTHROPIC_API_KEY not set";
    return 0;
}

static void anthropic_prepare_availability(const char *name, struct provider_availability *out)
{
    (void)name;
    const char *reason = NULL;
    out->available = anthropic_key_available("ANTHROPIC_API_KEY", &reason);
    out->reason = reason;
}

const struct provider_factory PROVIDER_ANTHROPIC = {
    .name = "anthropic",
    .new = anthropic_provider_new,
    .prepare_availability = anthropic_prepare_availability,
};

